import{_ as e,o as r,c as d,a2 as n}from"./chunks/framework.DU2spEDf.js";const h=JSON.parse('{"title":"Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"glossary.md","filePath":"glossary.md","lastUpdated":1787906606000}'),o={name:"glossary.md"};function a(s,t,i,c,g,l){return r(),d("div",null,[...t[0]||(t[0]=[n('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><p>This glossary defines the key technical, business, and platform-specific terms used throughout the Ishuko documentation.</p><table tabindex="0"><thead><tr><th>Term</th><th>Definition</th><th>Category</th></tr></thead><tbody><tr><td><strong>Admin</strong></td><td>A user with elevated privileges who can manage and monitor the Ishuko platform.</td><td>User Management</td></tr><tr><td><strong>Admin Dashboard</strong></td><td>The web interface used by authorized administrators to manage and monitor the Ishuko platform.</td><td>Platform</td></tr><tr><td><strong>AI</strong></td><td>Artificial Intelligence; technology that enables software to perform tasks that normally require human intelligence.</td><td>Technology</td></tr><tr><td><strong>AI Grading</strong></td><td>The process of using artificial intelligence to assess and classify agricultural produce.</td><td>AI</td></tr><tr><td><strong>AI Grading Result</strong></td><td>The output generated after the AI has assessed agricultural produce.</td><td>AI</td></tr><tr><td><strong>API</strong></td><td>Application Programming Interface; a set of rules and endpoints that allows different software components to communicate.</td><td>Backend</td></tr><tr><td><strong>API Client</strong></td><td>A component responsible for sending requests to and receiving responses from the backend API.</td><td>Backend</td></tr><tr><td><strong>API Endpoint</strong></td><td>A specific URL through which a client can interact with a particular backend function or resource.</td><td>Backend</td></tr><tr><td><strong>Authentication</strong></td><td>The process of verifying the identity of a user or system.</td><td>Security</td></tr><tr><td><strong>Authorization</strong></td><td>The process of determining what an authenticated user is permitted to access or perform.</td><td>Security</td></tr><tr><td><strong>Audit Log</strong></td><td>A record of important actions and events performed within the system for accountability, security, and troubleshooting.</td><td>Security</td></tr><tr><td><strong>Backend</strong></td><td>The server-side component responsible for business logic, database operations, APIs, authentication, and integrations.</td><td>Architecture</td></tr><tr><td><strong>Base URL</strong></td><td>The root URL used when communicating with the backend API.</td><td>Backend</td></tr><tr><td><strong>Business Logic</strong></td><td>The rules and processes that determine how the Ishuko platform operates.</td><td>Backend</td></tr><tr><td><strong>Client</strong></td><td>An application that communicates with the backend API, such as a mobile application or admin dashboard.</td><td>Architecture</td></tr><tr><td><strong>CRUD</strong></td><td>Create, Read, Update, Delete; the four fundamental operations performed on application data.</td><td>Database</td></tr><tr><td><strong>Database</strong></td><td>A structured system used to store, organize, and retrieve application data.</td><td>Database</td></tr><tr><td><strong>Database Model</strong></td><td>A software representation of a database entity and its fields.</td><td>Database</td></tr><tr><td><strong>Database Migration</strong></td><td>A controlled change to the structure of the database, such as adding tables or columns.</td><td>Database</td></tr><tr><td><strong>Dependency</strong></td><td>A library, package, service, or component required by another part of the application.</td><td>Development</td></tr><tr><td><strong>Dependency Injection</strong></td><td>A design pattern in which dependencies are provided to a component instead of being created directly within it.</td><td>Development</td></tr><tr><td><strong>Edge AI</strong></td><td>Artificial intelligence processing performed locally or near the device where data is collected rather than relying entirely on cloud processing.</td><td>AI</td></tr><tr><td><strong>Environment Variable</strong></td><td>A configuration value stored outside application source code, often used for URLs, credentials, and secret keys.</td><td>Configuration</td></tr><tr><td><strong><code>.env</code></strong></td><td>A configuration file commonly used during development to store environment variables.</td><td>Configuration</td></tr><tr><td><strong>Firebase</strong></td><td>A Google platform providing services such as authentication, notifications, analytics, and other application services.</td><td>Integration</td></tr><tr><td><strong>Foreign Key</strong></td><td>A database field that establishes a relationship between records in different database tables.</td><td>Database</td></tr><tr><td><strong>FastAPI</strong></td><td>A Python web framework used to build the Ishuko backend API.</td><td>Technology</td></tr><tr><td><strong>Grading</strong></td><td>The process of assessing agricultural produce according to predefined quality criteria.</td><td>Business</td></tr><tr><td><strong>HTTP</strong></td><td>Hypertext Transfer Protocol; a communication protocol used for transferring data between clients and servers.</td><td>Web</td></tr><tr><td><strong>HTTPS</strong></td><td>Hypertext Transfer Protocol Secure; the encrypted version of HTTP.</td><td>Security</td></tr><tr><td><strong>HTTP Status Code</strong></td><td>A numerical response returned by a server indicating the result of an HTTP request.</td><td>Backend</td></tr><tr><td><strong>ID</strong></td><td>Identifier; a unique value used to identify a specific record or resource.</td><td>Database</td></tr><tr><td><strong>Integration</strong></td><td>A connection between Ishuko and an external service or system.</td><td>Architecture</td></tr><tr><td><strong>Index</strong></td><td>A database structure used to improve the speed of data retrieval.</td><td>Database</td></tr><tr><td><strong>Ishuko</strong></td><td>The agricultural technology platform being developed to support users and agricultural processes within the target market.</td><td>Platform</td></tr><tr><td><strong>JSON</strong></td><td>JavaScript Object Notation; a lightweight data format commonly used for API communication.</td><td>Backend</td></tr><tr><td><strong>JWT</strong></td><td>JSON Web Token; a token format commonly used to securely transmit authentication information.</td><td>Security</td></tr><tr><td><strong>Logging</strong></td><td>The process of recording application events, errors, warnings, and system activities.</td><td>Monitoring</td></tr><tr><td><strong>Middleware</strong></td><td>Software that runs between an incoming request and the application&#39;s main request handler.</td><td>Backend</td></tr><tr><td><strong>Model</strong></td><td>A representation of an application or database entity.</td><td>Backend</td></tr><tr><td><strong>Mobile Application</strong></td><td>The user-facing application through which users interact with Ishuko services.</td><td>Platform</td></tr><tr><td><strong>Notification</strong></td><td>A message generated by the system to inform a user about an event or action.</td><td>Platform</td></tr><tr><td><strong>Notification Service</strong></td><td>A backend component responsible for creating, managing, and delivering notifications.</td><td>Backend</td></tr><tr><td><strong>ORM</strong></td><td>Object-Relational Mapping; a technique that allows developers to interact with relational databases using programming objects.</td><td>Database</td></tr><tr><td><strong>Payment</strong></td><td>A financial transaction processed through the Ishuko platform.</td><td>Payments</td></tr><tr><td><strong>Payment Gateway</strong></td><td>A service that facilitates electronic payment processing.</td><td>Payments</td></tr><tr><td><strong>Payment Status</strong></td><td>The current state of a payment, such as pending, successful, failed, cancelled, or refunded.</td><td>Payments</td></tr><tr><td><strong>Permission</strong></td><td>A rule determining whether a user is allowed to perform an action or access a resource.</td><td>Security</td></tr><tr><td><strong>Primary Key</strong></td><td>A database field that uniquely identifies each record in a table.</td><td>Database</td></tr><tr><td><strong>Pydantic</strong></td><td>A Python library used for data validation and serialization, particularly with FastAPI.</td><td>Technology</td></tr><tr><td><strong>Python</strong></td><td>The programming language used to develop the Ishuko backend.</td><td>Technology</td></tr><tr><td><strong>Query</strong></td><td>A request used to retrieve or manipulate data in a database.</td><td>Database</td></tr><tr><td><strong>Query Parameter</strong></td><td>An optional value included in an API URL to provide filtering, searching, sorting, or pagination information.</td><td>API</td></tr><tr><td><strong>RBAC</strong></td><td>Role-Based Access Control; a security model where permissions are assigned according to user roles.</td><td>Security</td></tr><tr><td><strong>Repository</strong></td><td>A backend layer responsible for interacting with the database.</td><td>Architecture</td></tr><tr><td><strong>Request</strong></td><td>A message sent by a client to the backend asking the server to perform an operation or return information.</td><td>API</td></tr><tr><td><strong>Response</strong></td><td>The message returned by the backend after processing a request.</td><td>API</td></tr><tr><td><strong>REST API</strong></td><td>Representational State Transfer API; an API architecture that uses HTTP methods and resources for communication.</td><td>API</td></tr><tr><td><strong>Role</strong></td><td>A classification assigned to a user that determines their permissions and level of access.</td><td>User Management</td></tr><tr><td><strong>Router</strong></td><td>A backend component that defines API endpoints and directs requests to the appropriate application logic.</td><td>Backend</td></tr><tr><td><strong>Schema</strong></td><td>A definition of the structure, fields, data types, and validation rules expected for application data.</td><td>Backend</td></tr><tr><td><strong>Security</strong></td><td>The mechanisms and practices used to protect the Ishuko platform, users, and data from unauthorized access or misuse.</td><td>Security</td></tr><tr><td><strong>Service</strong></td><td>A backend layer responsible for implementing business logic and coordinating application operations.</td><td>Architecture</td></tr><tr><td><strong>Session</strong></td><td>A period during which a user interacts with the application while authenticated.</td><td>Authentication</td></tr><tr><td><strong>SQL</strong></td><td>Structured Query Language; a language used to interact with relational databases.</td><td>Database</td></tr><tr><td><strong>Status</strong></td><td>A value representing the current state of a resource or process.</td><td>General</td></tr><tr><td><strong>Soft Delete</strong></td><td>A deletion approach where a record remains in the database but is marked as deleted or inactive.</td><td>Database</td></tr><tr><td><strong>Token</strong></td><td>A digital value used to represent authentication or authorization information.</td><td>Security</td></tr><tr><td><strong>Transaction</strong></td><td>A recorded business or financial operation performed through the Ishuko platform.</td><td>Business</td></tr><tr><td><strong>Third-Party Service</strong></td><td>An external service integrated with Ishuko to provide additional functionality.</td><td>Integration</td></tr><tr><td><strong>UI</strong></td><td>User Interface; the visual elements through which users interact with the application.</td><td>Design</td></tr><tr><td><strong>User</strong></td><td>An individual who interacts with the Ishuko platform.</td><td>User Management</td></tr><tr><td><strong>User ID</strong></td><td>A unique identifier assigned to a user account.</td><td>User Management</td></tr><tr><td><strong>User Role</strong></td><td>A role assigned to a user that determines their access and permissions.</td><td>User Management</td></tr><tr><td><strong>Validation</strong></td><td>The process of checking whether data meets predefined requirements and rules.</td><td>Backend</td></tr><tr><td><strong>Version Control</strong></td><td>A system used to track and manage changes to source code and project files.</td><td>Development</td></tr><tr><td><strong>Webhook</strong></td><td>An HTTP callback used by an external service to notify Ishuko when a specific event occurs.</td><td>Integration</td></tr><tr><td><strong>Web Application</strong></td><td>An application accessed through a web browser. The Ishuko Admin Dashboard is an example.</td><td>Platform</td></tr></tbody></table><h2 id="technical-abbreviations" tabindex="-1">Technical Abbreviations <a class="header-anchor" href="#technical-abbreviations" aria-label="Permalink to &quot;Technical Abbreviations&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Abbreviation</th><th>Full Meaning</th><th>Description</th></tr></thead><tbody><tr><td><strong>AI</strong></td><td>Artificial Intelligence</td><td>Technology used to perform tasks that normally require human intelligence.</td></tr><tr><td><strong>API</strong></td><td>Application Programming Interface</td><td>Interface that enables communication between software components.</td></tr><tr><td><strong>CRUD</strong></td><td>Create, Read, Update, Delete</td><td>Fundamental operations for managing data.</td></tr><tr><td><strong>DB</strong></td><td>Database</td><td>System used to store and manage application data.</td></tr><tr><td><strong>DTO</strong></td><td>Data Transfer Object</td><td>Object used to transfer data between different parts of an application.</td></tr><tr><td><strong>HTTP</strong></td><td>Hypertext Transfer Protocol</td><td>Protocol used for communication between clients and servers.</td></tr><tr><td><strong>HTTPS</strong></td><td>Hypertext Transfer Protocol Secure</td><td>Secure and encrypted version of HTTP.</td></tr><tr><td><strong>ID</strong></td><td>Identifier</td><td>A unique value used to identify a resource.</td></tr><tr><td><strong>JSON</strong></td><td>JavaScript Object Notation</td><td>Data format commonly used for API communication.</td></tr><tr><td><strong>JWT</strong></td><td>JSON Web Token</td><td>Token format commonly used for authentication.</td></tr><tr><td><strong>ORM</strong></td><td>Object-Relational Mapping</td><td>Technique for interacting with databases using programming objects.</td></tr><tr><td><strong>RBAC</strong></td><td>Role-Based Access Control</td><td>Security model based on user roles and permissions.</td></tr><tr><td><strong>REST</strong></td><td>Representational State Transfer</td><td>Architectural style commonly used for web APIs.</td></tr><tr><td><strong>SQL</strong></td><td>Structured Query Language</td><td>Language used to interact with relational databases.</td></tr><tr><td><strong>UI</strong></td><td>User Interface</td><td>Visual interface through which users interact with the application.</td></tr><tr><td><strong>URL</strong></td><td>Uniform Resource Locator</td><td>Address used to locate a resource on a network.</td></tr><tr><td><strong>UUID</strong></td><td>Universally Unique Identifier</td><td>Identifier designed to be unique across systems.</td></tr></tbody></table><h2 id="common-http-status-codes" tabindex="-1">Common HTTP Status Codes <a class="header-anchor" href="#common-http-status-codes" aria-label="Permalink to &quot;Common HTTP Status Codes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status Code</th><th>Meaning</th><th>Description</th></tr></thead><tbody><tr><td><strong>200</strong></td><td>OK</td><td>The request was successfully processed.</td></tr><tr><td><strong>201</strong></td><td>Created</td><td>A new resource was successfully created.</td></tr><tr><td><strong>400</strong></td><td>Bad Request</td><td>The request contains invalid or malformed information.</td></tr><tr><td><strong>401</strong></td><td>Unauthorized</td><td>Authentication is required or has failed.</td></tr><tr><td><strong>403</strong></td><td>Forbidden</td><td>The user is authenticated but does not have permission to perform the requested action.</td></tr><tr><td><strong>404</strong></td><td>Not Found</td><td>The requested resource could not be found.</td></tr><tr><td><strong>409</strong></td><td>Conflict</td><td>The request conflicts with the current state of the resource.</td></tr><tr><td><strong>422</strong></td><td>Unprocessable Entity</td><td>The request contains validation errors.</td></tr><tr><td><strong>500</strong></td><td>Internal Server Error</td><td>An unexpected error occurred on the server.</td></tr></tbody></table><h2 id="ishuko-specific-terms" tabindex="-1">Ishuko-Specific Terms <a class="header-anchor" href="#ishuko-specific-terms" aria-label="Permalink to &quot;Ishuko-Specific Terms&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Definition</th></tr></thead><tbody><tr><td><strong>Ishuko Platform</strong></td><td>The complete ecosystem consisting of the user-facing applications, backend services, database, AI functionality, payment services, notifications, and administrative tools.</td></tr><tr><td><strong>Ishuko Admin Dashboard</strong></td><td>The administrative web application used to manage and monitor platform activities.</td></tr><tr><td><strong>AI Grading System</strong></td><td>The component responsible for processing produce assessment and generating grading results.</td></tr><tr><td><strong>Produce Grading</strong></td><td>The process of evaluating and classifying agricultural produce according to defined quality standards.</td></tr><tr><td><strong>AI Grading Result</strong></td><td>The recorded output of the AI grading process.</td></tr><tr><td><strong>Payment Record</strong></td><td>A database record containing information about a payment transaction.</td></tr><tr><td><strong>Audit Log</strong></td><td>A historical record of significant actions performed within the platform.</td></tr><tr><td><strong>Notification</strong></td><td>A system-generated message informing a user about an event or change.</td></tr><tr><td><strong>Edge-Based AI</strong></td><td>AI processing performed locally or close to the point where produce is assessed, reducing reliance on remote image storage and processing.</td></tr><tr><td><strong>Role</strong></td><td>A predefined set of permissions assigned to a user.</td></tr><tr><td><strong>Permission</strong></td><td>An individual access rule determining what an authorized user can do within the platform.</td></tr></tbody></table><hr><h2 id="related-documentation" tabindex="-1">Related Documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to &quot;Related Documentation&quot;">​</a></h2><p>For detailed information about the concepts in this glossary, refer to the relevant sections of the Ishuko documentation:</p><ul><li>Architecture Documentation</li><li>Backend Documentation</li><li>API Documentation</li><li>Database Documentation</li><li>Authentication &amp; Authorization Documentation</li><li>AI Grading Documentation</li><li>Payment Documentation</li><li>Notification Documentation</li><li>Admin Dashboard Documentation</li><li>Security Documentation</li><li>Deployment Documentation</li></ul><hr><h2 id="maintenance" tabindex="-1">Maintenance <a class="header-anchor" href="#maintenance" aria-label="Permalink to &quot;Maintenance&quot;">​</a></h2><p>This glossary should be updated whenever a new technical term, platform feature, service, abbreviation, or domain-specific concept is introduced into the Ishuko system.</p>',16)])])}const m=e(o,[["render",a]]);export{h as __pageData,m as default};
